function getRainSteps(itemId, lang, type = "crop") {
  const phases = { before: [RAIN_GENERIC.before[lang]], during: [RAIN_GENERIC.during[lang]], after: [RAIN_GENERIC.after[lang]] };
  const extra = type === "fruit" ? RAIN_FRUIT_TIP[itemId] : RAIN_CROP_TIP[itemId];
  if (extra) phases[extra.phase].push(extra[lang]);
  return phases;
}

