/* -------------------------------- HELPERS ---------------------------------- */
function cleanMarkdown(text) {
  return text
    .replace(/\*\*(.*?)\*\*/g, "$1")
    .replace(/(?<!\*)\*([^*]+)\*(?!\*)/g, "$1")
    .replace(/^#{1,6}\s*/gm, "")
    .replace(/`{1,3}/g, "")
    .trim();
}
function stripForSpeech(text) {
  return cleanMarkdown(text)
    // strip emoji & pictographic symbols so TTS doesn't read out their names
    .replace(/[\u{1F1E6}-\u{1F1FF}\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}\u{2190}-\u{21FF}\u{2B00}-\u{2BFF}\u{FE0F}\u{200D}]/gu, "")
    .replace(/\s{2,}/g, " ")
    .trim();
}
let _voicesCache = null;
function getVoiceFor(langCode) {
  if (!window.speechSynthesis) return null;
  const voices = _voicesCache && _voicesCache.length ? _voicesCache : window.speechSynthesis.getVoices();
  if (voices && voices.length) _voicesCache = voices;
  if (!voices || !voices.length) return null;
  const prefix = langCode.split("-")[0];
  return voices.find((v) => v.lang === langCode) || voices.find((v) => v.lang && v.lang.toLowerCase().startsWith(prefix)) || null;
}
function voiceAvailable(langCode) {
  if (!window.speechSynthesis) return false;
  const voices = _voicesCache && _voicesCache.length ? _voicesCache : window.speechSynthesis.getVoices();
  if (voices && voices.length) _voicesCache = voices;
  if (!voices || !voices.length) return true; // voice list not loaded yet — don't block the attempt
  const prefix = langCode.split("-")[0];
  return voices.some((v) => v.lang && v.lang.toLowerCase().startsWith(prefix));
}
function hasInstalledVoice(langCode) {
  if (!window.speechSynthesis) return false;
  const voices = _voicesCache && _voicesCache.length ? _voicesCache : window.speechSynthesis.getVoices();
  if (voices && voices.length) _voicesCache = voices;
  if (!voices || !voices.length) return false;
  const prefix = langCode.split("-")[0];
  return voices.some((v) => v.lang && v.lang.toLowerCase().startsWith(prefix));
}
function speakText(text, langCode, onend) {
  try {
    if (!window.speechSynthesis) return null;
    window.speechSynthesis.cancel();
    const clean = stripForSpeech(text);
    if (!clean) { if (onend) onend(); return null; }
    const u = new SpeechSynthesisUtterance(clean);
    u.lang = langCode;
    u.rate = 0.92;
    const voice = getVoiceFor(langCode);
    if (voice) u.voice = voice;
    if (onend) u.onend = onend;
    window.speechSynthesis.speak(u);
    return u;
  } catch (e) { return null; }
}
if (typeof window !== "undefined" && window.speechSynthesis) {
  window.speechSynthesis.onvoiceschanged = () => { _voicesCache = window.speechSynthesis.getVoices(); };
}
const LANG_CODE = { en: "en-IN", hi: "hi-IN", mr: "mr-IN" };
