function analyzePixels(imgEl) {
  const canvas = document.createElement("canvas");
  const size = 120;
  canvas.width = size; canvas.height = size;
  const ctx = canvas.getContext("2d");
  ctx.drawImage(imgEl, 0, 0, size, size);
  const { data } = ctx.getImageData(0, 0, size, size);
  let green = 0, yellow = 0, brown = 0, dark = 0, total = 0;
  for (let i = 0; i < data.length; i += 4) {
    const r = data[i], g = data[i + 1], b = data[i + 2];
    total++;
    const brightness = (r + g + b) / 3;
    if (brightness < 60) { dark++; continue; }
    if (g > r && g > b && g > 70) { green++; continue; }
    if (r > 120 && g > 90 && b < 90 && Math.abs(r - g) < 70) { yellow++; continue; }
    if (r > 60 && r < 160 && g < r && b < g) { brown++; continue; }
  }
  const gr = green / total, yr = yellow / total, br = brown / total, dr = dark / total;
  let condition = "healthy";
  let score = Math.round(Math.min(97, 55 + gr * 60 - yr * 40 - br * 50 - dr * 30));
  if (br > 0.10 && br >= yr && br >= dr * 0.7) condition = "early_blight";
  else if (yr > 0.14 && yr > br) condition = "nutrient_deficiency";
  else if (dr > 0.08 && dr > yr && dr > br) condition = "pest_damage";
  else if (gr > 0.5) condition = "healthy";
  else condition = yr >= br ? "nutrient_deficiency" : "early_blight";
  score = Math.max(18, Math.min(97, score));
  const confidence = Math.round(50 + Math.abs(gr - Math.max(yr, br, dr)) * 90);
  return { condition, score, confidence: Math.max(38, Math.min(96, confidence)) };
}

function checkImageQuality(imgEl) {
  const canvas = document.createElement("canvas");
  const size = 100;
  canvas.width = size; canvas.height = size;
  const ctx = canvas.getContext("2d");
  ctx.drawImage(imgEl, 0, 0, size, size);
  const { data } = ctx.getImageData(0, 0, size, size);
  const gray = new Float32Array(size * size);
  let brightnessSum = 0, greenish = 0;
  for (let i = 0, p = 0; i < data.length; i += 4, p++) {
    const r = data[i], g = data[i + 1], b = data[i + 2];
    const lum = 0.299 * r + 0.587 * g + 0.114 * b;
    gray[p] = lum;
    brightnessSum += lum;
    if (g > r * 0.95 && g > b * 0.95 && g > 55) greenish++;
  }
  const avgBrightness = brightnessSum / gray.length;
  const greenRatio = greenish / gray.length;

  // crude blur estimate: variance of a simple Laplacian (edge strength) —
  // sharp photos have strong local contrast, blurry ones don't.
  let edgeSum = 0, edgeCount = 0;
  for (let y = 1; y < size - 1; y++) {
    for (let x = 1; x < size - 1; x++) {
      const idx = y * size + x;
      const lap = Math.abs(4 * gray[idx] - gray[idx - 1] - gray[idx + 1] - gray[idx - size] - gray[idx + size]);
      edgeSum += lap;
      edgeCount++;
    }
  }
  const sharpness = edgeSum / edgeCount;

  if (avgBrightness < 42) return "dark";
  if (sharpness < 6) return "blurry";
  // Fruit, flowers, soil-background and fish images may not be green.
  // Do not reject a clear image merely because it lacks green pixels.
  return "good";
}

async function fetchWeather(lat, lon) {
  const url = `https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&current=temperature_2m,relative_humidity_2m,precipitation,weather_code,wind_speed_10m,apparent_temperature&daily=precipitation_probability_max,precipitation_sum,temperature_2m_max,temperature_2m_min,weather_code&forecast_days=4&timezone=auto`;
  const res = await fetch(url);
  if (!res.ok) throw new Error("weather fetch failed");
  const json = await res.json();
  const daily = (json.daily.time || []).map((date, i) => ({
    date,
    pop: json.daily.precipitation_probability_max?.[i] ?? 0,
    sum: json.daily.precipitation_sum?.[i] ?? 0,
    tmax: json.daily.temperature_2m_max?.[i],
    tmin: json.daily.temperature_2m_min?.[i],
    code: json.daily.weather_code?.[i] ?? 2,
  }));
  return {
    current: {
      temp: Math.round(json.current.temperature_2m),
      humidity: Math.round(json.current.relative_humidity_2m),
      code: json.current.weather_code,
      wind: Math.round(json.current.wind_speed_10m ?? 0),
      feelsLike: Math.round(json.current.apparent_temperature ?? json.current.temperature_2m),
    },
    daily,
  };
}

function findRainAlert(daily) {
  for (let i = 1; i < daily.length; i++) {
    const d = daily[i];
    if (d.pop >= 70 || d.sum >= 25) {
      return { daysAhead: i, pop: d.pop, sum: Math.round(d.sum), date: d.date };
    }
  }
  return null;
}

function getFarmAdvisoryKey(current) {
  if (!current) return null;
  if (current.wind >= 25) return "advisoryWindy";
  if (current.humidity >= 80) return "advisoryHumid";
  if (current.temp >= 38) return "advisoryHot";
  return "advisoryGood";
}

/* -------------------------- MANDI PRICES (via backend) -----------------------
   The real Agmarknet (data.gov.in) key lives server-side in backend/.env —
   never in this frontend file. This just calls your backend, which proxies
   the request. If the backend has no key configured yet, it returns null and
   the app does not show a sample price; it shows a clear unavailable state until live data is returned.
------------------------------------------------------------------------------- */
async function fetchAgmarknetPrice(commodityName, filters = {}) {
  try {
    const params = new URLSearchParams({ commodity: commodityName });
    Object.entries(filters).forEach(([key, value]) => {
      if (value) params.set(key, value);
    });
    const res = await fetch(`${API_BASE}/prices?${params.toString()}`);
    if (!res.ok) return null;
    const data = await res.json();
    const records = Array.isArray(data?.records) ? data.records : [];
    return { ...data, records };
  } catch (e) {
    return null;
  }
}

/* --------------------------- CLOUD TEXT-TO-SPEECH ----------------------------
   The backend calls ElevenLabs with a server-side key. This keeps the key out
   of the browser and gives the app a reliable multilingual TTS path for
   English, Hindi, and Marathi, with device speechSynthesis as a fallback.
------------------------------------------------------------------------------- */
const TTS_BACKEND_URL = `${API_BASE}/tts`; // Backend routes en/hi to ElevenLabs and mr to Sarvam; selected language is passed on every request.

const TTS_CACHE = new Map();
const TTS_INFLIGHT = new Map();
async function synthesizeSpeechCloud(text, langCode) {
  if (!TTS_BACKEND_URL) return null;
  const speechText = stripForSpeech(text);
  if (!speechText) return null;
  const cacheKey = `${langCode}::${speechText}`;
  if (TTS_CACHE.has(cacheKey)) return TTS_CACHE.get(cacheKey);
  if (TTS_INFLIGHT.has(cacheKey)) return TTS_INFLIGHT.get(cacheKey);
  const request = (async () => {
    try {
      const res = await fetch(TTS_BACKEND_URL, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ text: speechText, lang: langCode }),
      });
      if (!res.ok) return null;
      const blob = await res.blob();
      if (!blob || blob.size === 0) return null;
      const url = URL.createObjectURL(blob);
      TTS_CACHE.set(cacheKey, url);
      return url;
    } catch (e) {
      return null;
    } finally {
      TTS_INFLIGHT.delete(cacheKey);
    }
  })();
  TTS_INFLIGHT.set(cacheKey, request);
  return request;
}

