/* -------------------------------- AI ASSISTANT ------------------------------- */
async function askAssistant({ question, imageBase64, imageMimeType = "image/jpeg", lang, fieldCrop, fieldFruit, fieldStage, weatherData, coords, marketPrices = {}, twinSummary, lastResult, treatmentData = [] }) {
  const langName = LANG_NAME[lang];
  const kbText = treatmentData.length
    ? treatmentData.map((x) => {
        const l = x.localized?.[lang] || {};
        return `- ${l.productName || x.productName}; ${l.productType || x.productType}; ${lang === "hi" ? "सक्रिय घटक" : lang === "mr" ? "सक्रिय घटक" : "active ingredient"}: ${x.activeIngredient}; ${lang === "hi" ? "उद्देश्य" : lang === "mr" ? "उद्देश" : "purpose"}: ${l.purpose || x.purpose}; ${lang === "hi" ? "उपयोग" : lang === "mr" ? "वापर" : "application"}: ${l.applicationGuidance || x.applicationGuidance}; ${lang === "hi" ? "सुरक्षा" : lang === "mr" ? "सुरक्षा" : "safety"}: ${l.safety || x.safety}; source: ${x.sourceUrl}`;
      }).join("\n")
    : "No verified treatment entry is available for this diagnosis. Say that treatment information is unavailable and advise consulting a local agricultural expert. Do not invent a product, chemical, dosage or image.";
  const cropObj = fieldCrop ? CROPS.find((c) => c.id === fieldCrop) : null;
  const fruitObj = fieldFruit ? FRUITS.find((c) => c.id === fieldFruit) : null;
  const cropLabel = cropObj ? (cropObj[lang] || cropObj.en) : (fruitObj ? (fruitObj[lang] || fruitObj.en) : (lang === "hi" ? "सेट नहीं है" : lang === "mr" ? "सेट केलेले नाही" : "not set"));
  const stageObj = fieldStage != null ? GROWTH_STAGES[fieldStage] : null;
  const stageLabel = stageObj ? (stageObj[lang] || stageObj.en) : (lang === "hi" ? "सेट नहीं है" : lang === "mr" ? "सेट केलेले नाही" : "not set");
  const weatherLabel = weatherData ? `${weatherData.current.temp}°C, ${weatherData.current.humidity}% ${lang === "hi" ? "नमी" : lang === "mr" ? "आर्द्रता" : "humidity"}, ${(weatherText(weatherData.current.code)[lang] || weatherText(weatherData.current.code).en)}` : (lang === "hi" ? "उपलब्ध नहीं" : lang === "mr" ? "उपलब्ध नाही" : "unavailable");
  const contextText = `${lang === "hi" ? "किसान की फसल" : lang === "mr" ? "शेतकऱ्याचे पीक" : "Farmer's crop"}: ${cropLabel}\n${lang === "hi" ? "वृद्धि चरण" : lang === "mr" ? "वाढीचा टप्पा" : "Growth stage"}: ${stageLabel}\n${lang === "hi" ? "आज का मौसम" : lang === "mr" ? "आजचे हवामान" : "Today's weather"}: ${weatherLabel}\n${lang === "hi" ? "फसल स्वास्थ्य रुझान" : lang === "mr" ? "पिकाच्या आरोग्याचा कल" : "Recent crop health trend"}: ${twinSummary || (lang === "hi" ? "अभी कोई स्कैन नहीं" : lang === "mr" ? "अजून स्कॅन नाही" : "no scan history yet")}\n${lang === "hi" ? "पत्ती जाँच का पिछला परिणाम" : lang === "mr" ? "मागील पान तपासणीचा निकाल" : "Last leaf-scan diagnosis"}: ${lastResult ? (ADVISORY[lastResult.condition]?.title?.[lang] || ADVISORY[lastResult.condition]?.title?.en) : (lang === "hi" ? "कोई नहीं" : lang === "mr" ? "काही नाही" : "none")}`;
  const answerLabels = {
    en: { cause: "Likely cause", check: "Check this now", today: "Do this today", prevent: "Prevent next time", watch: "Watch for" },
    hi: { cause: "संभावित कारण", check: "अभी यह देखें", today: "आज यह करें", prevent: "अगली बार बचाव", watch: "इन बातों पर ध्यान दें" },
    mr: { cause: "संभाव्य कारण", check: "आत्ता हे तपासा", today: "आज हे करा", prevent: "पुढच्या वेळी बचाव", watch: "याकडे लक्ष द्या" },
  }[lang] || { cause: "Likely cause", check: "Check this now", today: "Do this today", prevent: "Prevent next time", watch: "Watch for" };

  const systemPrompt = `You are Farmora (Sevak), a reliable farming and fisheries/aquaculture assistant for Indian smallholder farmers and fish farmers.
LANGUAGE LOCK: The selected answer language is ${langName}. Write the ENTIRE answer only in ${langName}. Do not translate into another language. Do not mix English, Hindi, Marathi, or another language into the answer. Keep product names such as Farmora, Sevak, and Agmarknet unchanged when they are proper names. Use the selected language for every instruction, explanation, label, warning, and sentence.
ANSWER REQUIREMENT: Always answer the farmer's actual question first. Never reply only with a generic failure message, a vague disclaimer, or "ask an expert" unless the case genuinely needs expert review. If the question is about weather, prices, crop care, farming methods, pond/water management, fish health, fish feed, or general knowledge, give a useful direct answer from reliable general knowledge and the farmer context. If exact live data is unavailable, clearly say that it is unavailable and still give the useful general guidance you can.
Use very simple everyday words a farmer would understand — short sentences, no unnecessary jargon.

When a farmer describes a common crop problem (yellow leaves, white spots, black spots, curling leaves, insects, wilting, etc.) OR a common pond/fish problem (green or foul water, fish gasping at the surface, slow growth, fish dying, disease spots on fish), your FIRST priority is to give real, practical, safe help — not to deflect to an expert. Format that kind of answer as short labelled lines, each starting with ONE relevant emoji so it is easy to scan even for someone who reads slowly, in this order:
🔍 ${answerLabels.cause} — one short line
👀 ${answerLabels.check} — 1-2 things to look for
✅ ${answerLabels.today} — immediate safe action(s)
🛡️ ${answerLabels.prevent} — a short prevention tip
📅 ${answerLabels.watch} — what to check over the next few days

Only recommend talking to a human expert when: your confidence is genuinely low, the symptoms described are unclear or could mean several different things, the problem sounds potentially serious (spreading fast, large area affected, unusual symptoms), or you have no verified information for this case. Do NOT default to "talk to an expert" as a first response — give the practical guidance above first, every time it's possible to do so safely.

For simple questions that aren't about a crop problem (prices, weather, general advice), skip the labelled format above and just answer in 1-3 short plain sentences, with at most one friendly emoji at the very start of the message.

For ANY pesticide, fertiliser, dosage, or treatment detail, use ONLY the knowledge base below — never invent a chemical name, dosage, or new treatment instruction that is not in the knowledge base. If a farmer's case genuinely needs expert review per the rule above, end your reply with exactly the token [NEED_EXPERT] on its own at the very end (after your practical guidance, not instead of it) — the app will show an "Ask an Expert" button when it sees this token. Keep the answer concise, normally under 220 words. Use short sections when the question needs detail, and do not omit important safety information just to make the answer shorter. Write in plain text only — no markdown symbols, no asterisks, no bold/italic markers, no headers, no bullet dashes — emoji labels ARE allowed and encouraged as described above, one per line, but do not use more than one emoji per line. This text is also read aloud by text-to-speech (emoji are automatically removed before speaking), so each line must still read as a natural full sentence once its emoji is removed.

KNOWLEDGE BASE:
${kbText}

FARMER CONTEXT:
${contextText}`;

  const contentBlocks = [];
  if (imageBase64) {
    contentBlocks.push({ type: "image", source: { type: "base64", media_type: imageMimeType, data: imageBase64 } });
  }
  contentBlocks.push({ type: "text", text: question });

  const response = await fetch(`${API_BASE}/assistant`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      max_tokens: 600,
      system: systemPrompt,
      // lang + context are required by the backend (backend/routes/assistant.js):
      // it uses `lang` to lock the reply language and `context.fieldCrop` /
      // `context.lastResult` to keep crop context across turns and to look up
      // verified products. Without these the backend silently defaults to
      // Marathi and loses the farmer's field/crop context.
      lang,
      question,
      context: {
        fieldCrop: fieldCrop || "",
        fieldFruit: fieldFruit || "",
        fieldStage: fieldStage != null ? fieldStage : null,
        coords: coords || null,
        weather: weatherData || null,
        marketPrices: marketPrices || {},
        lastResult: lastResult ? { condition: lastResult.condition } : null,
      },
      messages: [{ role: "user", content: contentBlocks }],
    }),
  });
  const data = await response.json().catch(() => ({}));
  if (!response.ok) {
    throw new Error(data.error || data.providerError || "The assistant request failed.");
  }
  const text = (data.content || []).map((c) => c.text || "").join("\n").trim();
  if (!text) throw new Error("The assistant returned an empty answer.");
  const products = Array.isArray(data.products) ? data.products : [];
  const images = Array.isArray(data.images) ? data.images : [];
  return {
    text, products, images,
    imageSearchUrl: data.imageSearchUrl || null,
    googleImageUrl: data.googleImageUrl || data.imageSearchUrl || null,
    googleSearchUrl: data.googleSearchUrl || null,
    shoppingUrl: data.shoppingUrl || null,
  };
}

/* ------------------------------- LEAF GAUGE --------------------------------- */
function LeafGauge({ score }) {
  const color = score >= 70 ? C.turf : score >= 45 ? C.wheat : C.red;
  const circumference = 2 * Math.PI * 54;
  const offset = circumference * (1 - score / 100);
  return (
    <div className="relative w-40 h-40 mx-auto">
      <svg viewBox="0 0 120 120" className="w-full h-full -rotate-90">
        <circle cx="60" cy="60" r="54" fill="none" stroke={C.paperDeep} strokeWidth="10" />
        <circle
          cx="60" cy="60" r="54" fill="none" stroke={color} strokeWidth="10"
          strokeDasharray={circumference} strokeDashoffset={offset}
          strokeLinecap="round" style={{ transition: "stroke-dashoffset 1s ease, stroke 0.6s ease" }}
        />
      </svg>
      <div className="absolute inset-0 flex flex-col items-center justify-center">
        <Leaf size={26} color={color} strokeWidth={2.2} />
        <span className="text-3xl font-extrabold" style={{ color: C.forest, fontFamily: "Poppins" }}>{score}</span>
        <span className="text-[10px] font-semibold tracking-wide" style={{ color: C.forest, opacity: 0.6 }}>/100</span>
      </div>
    </div>
  );
}

function MiniBar({ score }) {
  const color = score >= 70 ? C.turf : score >= 45 ? C.wheat : C.red;
  const h = Math.max(8, Math.round((score / 100) * 40));
  return <div className="w-4 rounded-t-sm" style={{ height: h, background: color }} />;
}

