  const optimizeImageForAI = useCallback((dataUrl, mimeType = "image/jpeg") => new Promise((resolve) => {
    const img = new window.Image();
    img.onload = () => {
      const maxSide = 1600;
      const scale = Math.min(1, maxSide / Math.max(img.naturalWidth || img.width, img.naturalHeight || img.height));
      const canvas = document.createElement("canvas");
      canvas.width = Math.max(1, Math.round((img.naturalWidth || img.width) * scale));
      canvas.height = Math.max(1, Math.round((img.naturalHeight || img.height) * scale));
      const ctx = canvas.getContext("2d", { alpha: false });
      ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
      const outputType = /png/i.test(mimeType) ? "image/png" : "image/jpeg";
      resolve(canvas.toDataURL(outputType, outputType === "image/jpeg" ? 0.88 : undefined));
    };
    img.onerror = () => resolve(dataUrl);
    img.src = dataUrl;
  }), []);

  const runAnalysis = useCallback(async (dataUrl) => {
    setAnalyzeError(null);
    setResult(null);
    setImgQuality(null);
    setAnalyzing(true);

    const img = new window.Image();
    img.onload = async () => {
      let quality = "good";
      try { quality = checkImageQuality(img); } catch (_) {}
      setImgQuality(quality);
      if (quality !== "good") {
        setAnalyzing(false);
        setAnalyzeError(
          quality === "dark" ? t.imgQualityDarkBody :
          quality === "blurry" ? t.imgQualityBlurryBody :
          t.imgQualityNoLeafBody
        );
        return;
      }

      try {
        const optimizedDataUrl = await optimizeImageForAI(dataUrl, dataUrl.match(/^data:([^;]+);base64,/)?.[1] || "image/jpeg");
        const base64 = optimizedDataUrl.split(",")[1];
        const mimeType = optimizedDataUrl.match(/^data:([^;]+);base64,/)?.[1] || "image/jpeg";
        const response = await fetch(`${API_BASE}/crop-scan`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            imageBase64: base64,
            mimeType,
            lang,
            fieldCrop: fieldCrop != null ? (CROPS.find((c) => c.id === fieldCrop)?.en || "") : (fieldFruit != null ? (FRUITS.find((c) => c.id === fieldFruit)?.en || "") : ""),
            fieldType: fieldFruit != null ? "fruit" : "crop",
          }),
        });
        const data = await response.json().catch(() => ({}));
        if (!response.ok) throw new Error(data.error || "Crop analysis unavailable");

        const condition = ["healthy", "early_blight", "nutrient_deficiency", "pest_damage", "unknown"].includes(data.conditionKey)
          ? data.conditionKey
          : "unknown";
        const confidence = Math.max(0, Math.min(100, Number(data.confidence) || 0));
        const r = {
          condition,
          score: confidence,
          confidence,
          crop: data.crop || "unknown",
          aiDiagnosis: data.diagnosis || "",
          uncertainty: data.uncertainty || "",
          symptoms: Array.isArray(data.symptoms) ? data.symptoms : [],
          nextActions: Array.isArray(data.nextActions) ? data.nextActions : [],
          prevention: Array.isArray(data.prevention) ? data.prevention : [],
          treatmentNote: data.treatmentNote || "",
          plantIdentification: data.plantIdentification || "",
          leafDetails: data.leafDetails || "",
          healthStatus: data.healthStatus || "",
          visualEvidence: Array.isArray(data.visualEvidence) ? data.visualEvidence : [],
          analysisSource: data.analysisSource || "AI",
        };
        setResult(r);
        setAnalyzing(false);
        setHistory((h) => [{ ...r, thumb: dataUrl, id: Date.now(), date: new Date() }, ...h].slice(0, 12));
      } catch (error) {
        console.error("Groq crop scan failed:", error);
        setAnalyzing(false);
        setAnalyzeError(t.analysisUnavailable);
      }
    };
    img.onerror = () => {
      setAnalyzing(false);
      setAnalyzeError(t.imgReadError);
    };
    img.src = dataUrl;
  }, [t, lang, fieldCrop, fieldFruit, optimizeImageForAI]);

